class Solution {
public:
    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        vector<vector<int>> coprimes(51);
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                if (gcd(i, j) == 1) coprimes[i].push_back(j);
            }
        }
        vector<int> ans(n, -1);
        vector<vector<pair<int, int>>> history(51);
        function<void(int, int, int)> dfs = [&](int u, int p, int d) {
            int val = nums[u];
            int bestDepth = -1, bestNode = -1;
            for (int c : coprimes[val]) {
                if (!history[c].empty()) {
                    auto [candNode, candDepth] = history[c].back();
                    if (candDepth > bestDepth) {
                        bestDepth = candDepth;
                        bestNode = candNode;
                    }
                }
            }
            ans[u] = bestNode;
            history[val].push_back({u, d});
            for (int v : adj[u]) {
                if (v != p) dfs(v, u, d + 1);
            }
            history[val].pop_back();
        };
        dfs(0, -1, 0);
        return ans;
    }
};

class Solution {
    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        List<List<Integer>> coprimes = new ArrayList<>();
        for (int i = 0; i <= 50; i++) coprimes.add(new ArrayList<>());
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                if (gcd(i, j) == 1) coprimes.get(i).add(j);
            }
        }
        int[] ans = new int[n];
        List<Deque<int[]>> history = new ArrayList<>();
        for (int i = 0; i <= 50; i++) history.add(new ArrayDeque<>());
        dfs(0, -1, 0, nums, adj, coprimes, history, ans);
        return ans;
    }
    private void dfs(int u, int p, int d, int[] nums, List<List<Integer>> adj,
                     List<List<Integer>> coprimes, List<Deque<int[]>> history, int[] ans) {
        int val = nums[u];
        int bestDepth = -1, bestNode = -1;
        for (int c : coprimes.get(val)) {
            if (!history.get(c).isEmpty()) {
                int[] cand = history.get(c).peek();
                if (cand[1] > bestDepth) {
                    bestDepth = cand[1];
                    bestNode = cand[0];
                }
            }
        }
        ans[u] = bestNode;
        history.get(val).push(new int[]{u, d});
        for (int v : adj.get(u)) {
            if (v != p) dfs(v, u, d + 1, nums, adj, coprimes, history, ans);
        }
        history.get(val).pop();
    }
}

var getCoprimes = function(nums, edges) {
    function gcd(a, b) {
        return b === 0 ? a : gcd(b, a % b);
    }
    const n = nums.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const coprimes = Array.from({ length: 51 }, () => []);
    for (let i = 1; i <= 50; i++) {
        for (let j = 1; j <= 50; j++) {
            if (gcd(i, j) === 1) coprimes[i].push(j);
        }
    }
    const ans = new Array(n).fill(-1);
    const history = Array.from({ length: 51 }, () => []);
    function dfs(u, p, d) {
        const val = nums[u];
        let bestDepth = -1, bestNode = -1;
        for (const c of coprimes[val]) {
            if (history[c].length > 0) {
                const [candNode, candDepth] = history[c][history[c].length - 1];
                if (candDepth > bestDepth) {
                    bestDepth = candDepth;
                    bestNode = candNode;
                }
            }
        }
        ans[u] = bestNode;
        history[val].push([u, d]);
        for (const v of adj[u]) {
            if (v !== p) dfs(v, u, d + 1);
        }
        history[val].pop();
    }
    dfs(0, -1, 0);
    return ans;
